/**
 * MaterialDTO Validator
 * to verify if account is bank, it must have a branch code
 * @author Co0der
 */
public class MaterialDTOValidator implements Validator {
    private Messages messages;

    public MaterialDTOValidator(Messages messages) {
        this.messages = messages;
    }
    /**
     * Can this {@link Validator} {@link #validate(Object, Errors) validate}
     * instances of the supplied {@code clazz}?
     */
    @Override
    public boolean supports(Class<?> clazz) {
        return MaterialDTO.class.isAssignableFrom(clazz);
    }

    /**
     * verify if account is bank, it must have a branch code
     *
     * @param obj
     * @param errors
     */
    @Override
    public void validate(Object obj, Errors errors) {
        MaterialDTO materialDTO = (MaterialDTO) obj;
        AccountType accountType = materialDTO.getPayAccountType();
        //accountType is bank
        if (accountType == AccountType.BANKCARD) {
            // payAccountName不能为空
            if (isBlank(materialDTO.getPayAccountName())) {
                errors.rejectValue("payAccountName", "error.invalid.parameter",
                        messages.getMessage("error.invalid.parameter"));// NOSONAR
            }
            // bankCode不能为空
            if (isBlank(materialDTO.getBankCode())) {
                errors.rejectValue("bankCode", "error.invalid.parameter",
                        messages.getMessage("error.invalid.parameter"));// NOSONAR
            }
            // branch Code不能为空
            if (isBlank(materialDTO.getBranchCode())) {
                errors.rejectValue("branchCode", "error.invalid.parameter",
                        messages.getMessage("error.invalid.parameter"));// NOSONAR
            } else if (materialDTO.getBranchCode().length() <= 1) {
                errors.rejectValue("branchCode", "error.invalid.parameter",
                        messages.getMessage("error.invalid.parameter"));// NOSONAR
            }
            // regionCode不能为空
            if (isBlank(materialDTO.getRegionCode())) {
                errors.rejectValue("regionCode", "error.invalid.parameter",
                        messages.getMessage("error.invalid.parameter"));// NOSONAR
            }
        }
    }
}
