@ApiOperation("提交账户信息")
    @PostMapping("")
    public GenericRpcResponse<Boolean> apply(@PathVariable String reportNo, @RequestBody @Valid MaterialDTO materialDTO) {
        /**
         * 获取userId
         */
        String userId = getUserId();
        notNull(materialDTO, "MaterialDTO is required!");
        /**
         * 实名校验
         */
        clientService.checkAuth(null, null, userId);
        try {
            validateMaterial(materialDTO);
            //提交资料
            boolean result = reportService.applyMaterial(materialDTO);
            return GenericRpcResponse.success(result);
        } catch (ExternalReportException e) {
            log.error("Applied material had exception, with MaterialDTO: {}", materialDTO, e);
            throw new ReportException("MaterialDTO.applyMaterial", e.getCode());
        }
